import { Component } from "./base/component";
import { AppEvents } from "../types";
import { ensureElement } from "../utils/utils";
export class Page extends Component {
    constructor(container, events) {
        super(container);
        this.container = container;
        this.gallery = ensureElement('.gallery', container);
        this.buttonElement = ensureElement('.header__basket', container);
        this.basketCounter = ensureElement('.header__basket-counter', container);
        this.events = events;
        this.buttonElement.addEventListener('click', () => events.emit(AppEvents["basket:open"]));
    }
    set catalog(items) {
        this.gallery.replaceChildren(...items);
    }
    set counter(value) {
        this.setText(this.basketCounter, value);
    }
}
