import { Component } from "./base/component";
import { ensureElement } from "../utils/utils";
export class Modal extends Component {
    constructor(container, events) {
        super(container);
        this.container = container;
        this.handleEscape = (evt) => {
            if (evt.key === 'Escape') {
                this.close();
            }
        };
        this.closeButton = ensureElement('.modal__close', container);
        this.contentElement = ensureElement('.modal__content', container);
        this.events = events;
        this.closeButton.addEventListener('click', () => this.close());
        this.container.addEventListener('click', () => this.close());
        this.contentElement.addEventListener('click', (event) => event.stopPropagation());
    }
    set content(content) {
        this.contentElement.replaceChildren(content);
    }
    toggleModal(state = true) {
        this.container.classList.toggle('modal_active', state);
    }
    open() {
        this.toggleModal();
        document.addEventListener('keydown', this.handleEscape);
    }
    close() {
        this.toggleModal(false);
        document.removeEventListener('keydown', this.handleEscape);
        this.content = null;
    }
    render(data) {
        Object.assign(this, data);
        this.open();
        return this.container;
    }
}
