import { Form } from "./Form";
import { AppEvents } from "../types";
export class ContactsForm extends Form {
    constructor(container, events) {
        super(container, events);
        this.container = container;
        this.events = events;
        this.inputElements.forEach(input => {
            input.addEventListener('input', (event) => {
                const field = input.name;
                const value = input.value;
                this.events.emit(AppEvents["contacts-field:input"], { field, value });
            });
        });
        container.addEventListener('submit', (event) => {
            event.preventDefault();
            this.events.emit(AppEvents["contacts-form:submit"]);
        });
    }
    set email(value) {
        this.container.elements.namedItem('email').value = value;
    }
    set phone(value) {
        this.container.elements.namedItem('phone').value = value;
    }
}
